const SALT_WORDS = new Set([
  "potassium", "sodium", "hydrochloride", "hcl", "calcium", "besylate", "maleate", "succinate",
  "tartrate", "mesylate", "citrate", "sulfate", "fumarate", "magnesium", "bromide", "hyclate",
