cd out && python3 - <<'EOF'
p='transform.ts'; s=open(p).read()
s=s.replace('''  if (/adverse|side effect|reaction|intoleran|allerg|associated|induced|toxicity|caused/.test(t)) return "adverse_reaction";''','''  if (/adverse|side effect|reaction|intoleran|allerg|associated|induced|toxicity|caused/.test(t) || SERIOUS_RE.test(t) || HYPERSENS_RE.test(t)) {
    return "adverse_reaction";
  }''')
s=s.replace('''      const reactionText =
        isObj(c.e.riverside_dx) && typeof c.e.riverside_dx.name === "string" && !isPureAdverseEffect(c)
          ? c.text.trim()
          : c.text.trim();
      let type = classifyReaction(reactionText, undefined);
      if (!SERIOUS_RE.test(reactionText) && !HYPERSENS_RE.test(reactionText) && !SIDE_RE.test(reactionText)) {
        type = "serious_adverse_event";
      }
      const criticality: AllergyIntoleranceRow["criticality"] =
        type === "serious_adverse_event" || /anaphyla|angioedema/i.test(reactionText) ? "high" : "unknown";''','''      const reactionText = c.text.trim();
      const pure = isPureAdverseEffect(c);
      const named = SERIOUS_RE.test(reactionText) || HYPERSENS_RE.test(reactionText) || SIDE_RE.test(reactionText);
      // A condition the hospital diagnosed and attributed to a drug is serious unless it names a
      // milder reaction; a bare "adverse effect of X" entry says nothing about the harm.
      let type: ReactionType = named ? classifyReaction(reactionText, undefined) : pure ? "side_effect" : "serious_adverse_event";
      const criticality: AllergyIntoleranceRow["criticality"] =
        (type === "serious_adverse_event" && !pure) || /anaphyla|angioedema/i.test(reactionText) ? "high" : "unknown";''')
open(p,'w').write(s)
EOF
cd .. && bun out/edge.ts | grep -E '"(substance|reaction_type|criticality|stop_reason)"' ; sh in/harness/check.sh >/dev/null && echo OK; bun out/peek.ts 2026-10-13 | grep -E "ALG|MED"
